<?php
declare(strict_types=1);
require dirname(__DIR__).'/config.php';require_once dirname(__DIR__).'/mgs-integration-lib.php';require_once dirname(__DIR__).'/inventory-operations-lib.php';
$db=app_db();$run=date('YmdHis').random_int(10,99);$itemId=0;$errors=[];$actor=['id'=>1,'role'=>'employee','employee_role'=>'warehouse','full_name'=>'Inventory Smoke'];
try{app_inventory_ensure_operational_schema($db);$s=$db->prepare('INSERT INTO inventory_stock_items(sku,item_name,category,unit,quantity_on_hand,minimum_quantity,status)VALUES(:sku,:name,"other","eded",0,0,"active")');$s->execute(['sku'=>'LOC-'.$run,'name'=>'Location Smoke '.$run]);$itemId=(int)$db->lastInsertId();
$in=app_inventory_post_intake($db,['item_id'=>$itemId,'quantity'=>10,'unit_price'=>12.5,'to_location_type'=>'branch','to_location_id'=>'1'],$actor);$tr=app_inventory_transfer_branch($db,['item_id'=>$itemId,'quantity'=>4,'from_branch_id'=>'1','to_branch_id'=>'2','note'=>'smoke'],$actor);
if(empty($in['ok'])||empty($tr['ok']))$errors[]='movement_failed';if(app_inventory_location_quantity($db,$itemId,'branch','1')!==6.0)$errors[]='source_delta';if(app_inventory_location_quantity($db,$itemId,'branch','2')!==4.0)$errors[]='target_delta';if(app_inventory_company_quantity($db,$itemId)!==10.0)$errors[]='global_changed';
$wh=app_inventory_post_intake($db,['item_id'=>$itemId,'quantity'=>5,'to_location_type'=>'warehouse','to_location_id'=>'MAIN'],$actor);$toBranch=app_inventory_transfer_branch($db,['item_id'=>$itemId,'quantity'=>2,'from_location'=>'warehouse:MAIN','to_location'=>'branch:1','note'=>'warehouse to branch'],$actor);$toWarehouse=app_inventory_transfer_branch($db,['item_id'=>$itemId,'quantity'=>1,'from_location'=>'branch:1','to_location'=>'warehouse:MAIN','note'=>'branch to warehouse'],$actor);
if(empty($wh['ok'])||empty($toBranch['ok'])||empty($toWarehouse['ok']))$errors[]='warehouse_transfer_failed';if(app_inventory_location_quantity($db,$itemId,'warehouse','MAIN')!==4.0)$errors[]='warehouse_delta';if(app_inventory_location_quantity($db,$itemId,'branch','1')!==7.0)$errors[]='branch_back_delta';if(app_inventory_company_quantity($db,$itemId)!==15.0)$errors[]='global_transfer_changed';
$bad=app_inventory_transfer_branch($db,['item_id'=>$itemId,'quantity'=>20,'from_branch_id'=>'1','to_branch_id'=>'2'],$actor);if(($bad['error']??'')!=='insufficient_stock')$errors[]='insufficient_not_blocked';
}finally{$db->prepare('DELETE FROM mgs_operation_actions WHERE actor_name="Inventory Smoke"')->execute();if($itemId){$db->prepare('DELETE FROM inventory_document_items WHERE item_id=:id')->execute(['id'=>$itemId]);$db->prepare('DELETE FROM inventory_documents WHERE entity_item_id=:id')->execute(['id'=>$itemId]);$db->prepare('DELETE FROM inventory_location_balances WHERE item_id=:id')->execute(['id'=>$itemId]);$db->prepare('DELETE FROM inventory_lifecycle_movements WHERE product_id=:id')->execute(['id'=>$itemId]);$db->prepare('DELETE FROM inventory_stock_movements WHERE item_id=:id')->execute(['id'=>$itemId]);$db->prepare('DELETE FROM inventory_stock_items WHERE id=:id')->execute(['id'=>$itemId]);}}
echo json_encode(['status'=>$errors===[]?'passed':'failed','errors'=>$errors],JSON_PRETTY_PRINT).PHP_EOL;exit($errors===[]?0:1);
